-- Content-free, restart-safe erasure inventory. Never stores canonical bodies.
CREATE TABLE brain_erasure_jobs (
 id TEXT PRIMARY KEY,state TEXT NOT NULL CHECK(state IN('scanning','review','deleting','verifying','purging','complete','cancelled')),
 folder_id TEXT,cursor TEXT,inventory_digest TEXT,
 scanned INTEGER NOT NULL DEFAULT 0,objects INTEGER NOT NULL DEFAULT 0,
 bytes INTEGER NOT NULL DEFAULT 0,deleted INTEGER NOT NULL DEFAULT 0,
 preserved INTEGER NOT NULL DEFAULT 0,busy_token TEXT,busy_until INTEGER NOT NULL DEFAULT 0,
 created_at TEXT NOT NULL,approved_at TEXT,completed_at TEXT
);
CREATE UNIQUE INDEX brain_one_active_erasure ON brain_erasure_jobs((1)) WHERE state NOT IN('complete','cancelled');
CREATE TABLE brain_erasure_items(
 job_id TEXT NOT NULL,drive_id TEXT NOT NULL,kind TEXT NOT NULL,
 content_hash TEXT NOT NULL,bytes INTEGER NOT NULL,markers TEXT NOT NULL,
 deleted INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(job_id,drive_id)
);
-- Optional, owner-reviewed pruning of access audit only; canonical history stays.
CREATE TABLE brain_audit_prunes(
 id TEXT PRIMARY KEY,state TEXT NOT NULL CHECK(state IN('review','deleting','complete','cancelled')),
 cutoff TEXT NOT NULL,retention_days INTEGER NOT NULL,high_water INTEGER NOT NULL,expected INTEGER NOT NULL,digest TEXT NOT NULL,
 deleted INTEGER NOT NULL DEFAULT 0,busy_token TEXT,busy_until INTEGER NOT NULL DEFAULT 0,
 created_at TEXT NOT NULL,completed_at TEXT
);
CREATE TABLE brain_audit_prune_items(job_id TEXT NOT NULL,audit_id INTEGER NOT NULL,PRIMARY KEY(job_id,audit_id));
CREATE INDEX audit_created_id ON audit(created_at,id);

-- An old in-flight request cannot repopulate erased content after passing a JS
-- preflight. Erasure writes its own job tables and deletes ordinary rows only.
CREATE TRIGGER cloudnest_erasure_fence_insert_memories BEFORE INSERT ON memories WHEN EXISTS(SELECT 1 FROM brain_config WHERE key IN('erasure_lock','account_erased')) BEGIN SELECT RAISE(ABORT,'CloudNest erasure maintenance is active'); END;
CREATE TRIGGER cloudnest_erasure_fence_update_memories BEFORE UPDATE ON memories WHEN EXISTS(SELECT 1 FROM brain_config WHERE key IN('erasure_lock','account_erased')) BEGIN SELECT RAISE(ABORT,'CloudNest erasure maintenance is active'); END;
